run_ct28.ps1.content:
param([Parameter(ValueFromRemainingArguments=$true)][string[]]$TrialArguments)
$ErrorActionPreference = 'Stop'
$ct28Container = (docker inspect caliburn-q019-postgres | ConvertFrom-Json)[0]
if ($LASTEXITCODE -ne 0 -or $ct28Container.State.Status -ne 'running') { throw 'Dedicated test database is not running' }
$ct28Settings = @{}
foreach ($ct28Entry in $ct28Container.Config.Env) {
    $ct28Pair = $ct28Entry.Split('=', 2)
    $ct28Settings[$ct28Pair[0]] = $ct28Pair[1]
}
if ($ct28Settings.POSTGRES_DB -ne 'q019_agent_test' -or $ct28Settings.POSTGRES_USER -ne 'q019') { throw 'Unexpected database identity' }
if ($ct28Container.NetworkSettings.Ports.'5432/tcp'[0].HostPort -ne '55433') { throw 'Unexpected port' }
$env:Q019_TEST_DATABASE_URL = 'postgresql://q019:' + [uri]::EscapeDataString($ct28Settings.POSTGRES_PASSWORD) + '@127.0.0.1:55433/q019_agent_test?connect_timeout=5'
$env:PYTHONUTF8 = '1'
$env:PYTHONPATH = 'src'
try {
    & .venv/Scripts/python.exe .test-tmp/ct28_run.py @TrialArguments
    $ct28Exit = $LASTEXITCODE
} finally {
    Remove-Item Env:Q019_TEST_DATABASE_URL -ErrorAction SilentlyContinue
    $ct28Settings.Clear()
}
exit $ct28Exit
